<div class="page-heading"><div><span class="eyebrow">MONEY MANAGEMENT</span><h1><?= e($title) ?></h1><p><?= $type==='income'?'Track the money coming into your business.':'Every expense, from draft to payment.' ?></p></div><a class="button primary" href="<?= e(url('entry',['type'=>$type])) ?>"><?= icon('plus') ?>Add <?= e($type) ?></a></div>
<section class="metrics"><div><span class="metric-label">Total recorded</span><strong><?= money($summary['total']) ?></strong><small>Matching entries</small></div><div><span class="metric-label">Paid</span><strong class="positive"><?= money($summary['paid']) ?></strong><small>Completed payments</small></div><div><span class="metric-label">Outstanding</span><strong><?= money($summary['pending']) ?></strong><small>Excludes drafts and rejected entries</small></div></section>
<form class="filter-bar" method="get"><input type="hidden" name="r" value="<?= $type==='income'?'income':'expenses' ?>"><label class="search-field"><?= icon('search') ?><input name="q" value="<?= e($search) ?>" placeholder="Search description or reference" aria-label="Search entries"></label><label><span class="sr-only">Month</span><input type="month" name="month" value="<?= e($month) ?>"></label><label><span class="sr-only">Status</span><select name="status"><option value="">All statuses</option><?php foreach($type==='income'?['draft','pending','paid']:['draft','pending','approved','paid','rejected'] as $s): ?><option value="<?= $s ?>"<?= selected($status,$s) ?>><?= ucfirst($s) ?></option><?php endforeach ?></select></label><button class="button" type="submit"><?= icon('filter') ?>Filter</button></form>
