<div class="pagination"><span><?= $count ?> entries &middot; Page <?= $page ?> of <?= max(1,(int)ceil($count/25)) ?></span><div><?php foreach([[$page-1,'chevron-left','Previous'],[$page+1,'chevron-right','Next']] as [$p,$i,$label]): if($p<1||$p>ceil($count/25)) continue; ?><a class="icon-button" aria-label="<?= $label ?> page" title="<?= $label ?>" href="<?= e(url($type==='income'?'income':'expenses',['month'=>$month,'status'=>$status,'q'=>$search,'page'=>$p])) ?>"><?= icon($i) ?></a><?php endforeach ?></div></div>
